import{_ as h,C as s,o as u,c,j as e,a as r,E as a,w as o,a3 as d}from"./chunks/framework.B02wg2PO.js";const v=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart/getting-started.md","filePath":"quickstart/getting-started.md"}'),p={name:"quickstart/getting-started.md"};function g(m,t,f,y,b,w){const i=s("Callout"),n=s("Card"),l=s("CardGrid");return u(),c("div",null,[t[5]||(t[5]=e("h1",{id:"getting-started",tabindex:"-1"},[r("Getting Started "),e("a",{class:"header-anchor",href:"#getting-started","aria-label":'Permalink to "Getting Started"'},"​")],-1)),t[6]||(t[6]=e("p",null,"Saidi is a hosted workspace. There is nothing to install and nothing to run — you create an account, name a workspace, and brief your first department.",-1)),a(i,{type:"tip",title:"Free while in early access"},{default:o(()=>[...t[0]||(t[0]=[e("p",null,"Every feature is open during early access: unlimited departments, agents, runs, schedules and reflexes, and no seat cap. Usage is metered in credits, and while early access lasts the credits are on us.",-1)])]),_:1}),t[7]||(t[7]=d('<h2 id="_1-create-your-account" tabindex="-1">1. Create your account <a class="header-anchor" href="#_1-create-your-account" aria-label="Permalink to &quot;1. Create your account&quot;">​</a></h2><p>Open the app and choose how you want to sign in:</p><table tabindex="0"><thead><tr><th>Method</th><th>What happens</th></tr></thead><tbody><tr><td>Email + password</td><td>You receive a verification link. Your account is limited until you click it.</td></tr><tr><td>Google</td><td>One redirect, no password to manage.</td></tr><tr><td>GitHub</td><td>Same, and the identity you will most likely want when connecting repos.</td></tr></tbody></table><p>Which providers appear on the login screen depends on what the platform has configured; email and password are always available.</p><h2 id="_2-name-your-workspace" tabindex="-1">2. Name your workspace <a class="header-anchor" href="#_2-name-your-workspace" aria-label="Permalink to &quot;2. Name your workspace&quot;">​</a></h2><p>A <strong>workspace</strong> (an org, internally) is the boundary around everything you create: agents, runs, chats, memory, schedules, reflexes, connections and the credit ledger. Nothing crosses between workspaces.</p><p>The first person to create a workspace is its <strong>owner</strong>. You can belong to more than one and switch between them from the account menu.</p><div class="info custom-block"><p class="custom-block-title">Joining instead of creating</p><p>If a colleague invited you, open their invite link rather than creating a workspace. The invite is locked to the email address it was sent to, and it carries the permissions the sender chose for you.</p></div><h2 id="_3-set-your-guardrails-—-before-anything-runs" tabindex="-1">3. Set your guardrails — before anything runs <a class="header-anchor" href="#_3-set-your-guardrails-—-before-anything-runs" aria-label="Permalink to &quot;3. Set your guardrails — before anything runs&quot;">​</a></h2><p>Do this now, not after your first surprise. In <strong>Settings</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Where</th><th>Why it matters first</th></tr></thead><tbody><tr><td>Approval mode</td><td>Approvals</td><td>Decides whether consequential actions pause for a human or proceed.</td></tr><tr><td>Spend ceiling</td><td>Costs &amp; Limits</td><td>A hard cap, checked <em>before</em> a call is made.</td></tr><tr><td>Tool permissions</td><td>Approvals</td><td>Per-agent control over what may read, write, run or publish.</td></tr></tbody></table>',11)),a(i,{type:"warning",title:"Agents write to real systems"},{default:o(()=>[...t[1]||(t[1]=[e("p",null,[r("Saidi commits and pushes to branches on repositories you connect, and can send mail and call external services. It never merges and never force-pushes — but set the approval mode and the ceiling you are comfortable with before your first autonomous run. See "),e("a",{href:"/docs/guides/guardrails"},"Approval & Spend Guardrails"),r(".")],-1)])]),_:1}),t[8]||(t[8]=d('<h2 id="_4-meet-the-console" tabindex="-1">4. Meet the console <a class="header-anchor" href="#_4-meet-the-console" aria-label="Permalink to &quot;4. Meet the console&quot;">​</a></h2><p>The left rail is the whole product:</p><table tabindex="0"><thead><tr><th>Section</th><th>What lives there</th></tr></thead><tbody><tr><td><strong>Home</strong></td><td>Your departments and agents at a glance — click one to look inside.</td></tr><tr><td><strong>Chat</strong></td><td>Where you brief Saidi. Multiple conversations, each with its own thread.</td></tr><tr><td><strong>Runs</strong></td><td>Every durable unit of work: in flight, waiting on you, or finished.</td></tr><tr><td><strong>Schedules</strong></td><td>Recurring runs on a cron.</td></tr><tr><td><strong>Reflexes</strong></td><td>Event triggers — a push lands, a run fails, a webhook fires.</td></tr><tr><td><strong>Memory</strong></td><td>What the workspace has learned and carries between runs.</td></tr><tr><td><strong>Market</strong></td><td>Skills, connectors, agents and whole departments to install.</td></tr><tr><td><strong>Settings</strong></td><td>Providers, costs, approvals, connections, team.</td></tr></tbody></table><p>Chat is where you talk to <strong>PRIME</strong> — the orchestrator you brief. Everything else is a window onto what PRIME did.</p><h2 id="_5-invite-your-team" tabindex="-1">5. Invite your team <a class="header-anchor" href="#_5-invite-your-team" aria-label="Permalink to &quot;5. Invite your team&quot;">​</a></h2><p>From <strong>Settings → Team</strong>, send an invite and pick that person&#39;s permissions as you do it. Runs and chats belong to whoever created them: no role, not even owner, reads another member&#39;s work unless it is explicitly shared with them.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2>',7)),a(l,{cols:3},{default:o(()=>[a(n,{title:"Your First Run",icon:"run",href:"/quickstart/first-run",badge:"5 min",cta:"Start a Run"},{default:o(()=>[...t[2]||(t[2]=[r(" Brief PRIME, watch the plan freeze, and read the result — end to end in one sitting. ",-1)])]),_:1}),a(n,{title:"Connect a repo",icon:"branch",href:"/quickstart/connecting-a-repo",cta:"Connecting a Repo"},{default:o(()=>[...t[3]||(t[3]=[r(" Point a project agent at a real repository and give it a worktree of its own. ",-1)])]),_:1}),a(n,{title:"Set your guardrails",icon:"shield",href:"/guides/guardrails",cta:"Guardrails"},{default:o(()=>[...t[4]||(t[4]=[r(" Approval mode, per-tool permissions and a spend ceiling — decide these before you go autonomous. ",-1)])]),_:1})]),_:1})])}const _=h(p,[["render",g]]);export{v as __pageData,_ as default};
